from taf.rfrl.l3_call.enviornment.classical_env.classical_gnb_sa_env import ClassicalEnvSA
from taf.rfrl.l3_call.enviornment.classical_env.classical_gnb_nsa_env import ClassicalEnvNSA
from taf.rfrl.l3_call.enviornment.cloud_env.cloud_env import CloudEnv
from taf.rfrl.l3_call.enviornment.classical_env.classical_enb_env import ClassicalEnvEnb
from taf.rfrl.l3_call.enviornment.exceptions import InvalidMode, InvalidNode, InvalidRan


class EnvFactory:
    """
    Creates ClassicalEnvSA, ClassicalEnvNSA, ClassicalEnvEnb or CloudEnvSA instances
    """

    @staticmethod
    def create_environment(ran, mode, node):
        """
        Creates ClassicalEnvSA, ClassicalEnvNSA, ClassicalEnvEnb or CloudEnvSA
        according to ran, mode and node

        :param ran: type of RAN classical/cloud
        :type ran: str
        :param mode: BTS setup mode SA/NSA
        :type mode: str
        :param node: type of node gnb/enb
        :type node: str
        :return: ClassicalEnvSA, ClassicalEnvNSA, ClassicalEnvEnb or CloudEnvSA
        :rtype: ClassicalEnvSA, ClassicalEnvNSA, ClassicalEnvEnb or CloudEnvSA

        :raises: InvalidMode if mode is incorrect
        :raises: InvalidNode if node is incorrect
        :raises: InvalidRan if ran is incorrect
        """
        if ran == "classical":
            if node == "gnb":
                if mode == "SA":
                    return ClassicalEnvSA()
                elif mode == "NSA":
                    return ClassicalEnvNSA()
                else:
                    raise InvalidMode("Mode must be either NSA or SA, you gave {}!".format(mode))

            elif node == "enb":
                return ClassicalEnvEnb()
            else:
                raise InvalidNode("Node must be either gnb or enb, you gave {}!".format(node))

        elif ran == "cloud":
            if node == "gnb":
                if mode == "SA":
                    return CloudEnv()
                else:
                    raise InvalidMode("The only mode available for cloud is SA, you have {}! "
                                      "Please contact taf.rfrl.l3_call developers".format(mode))
            else:
                raise InvalidNode("The only node available for cloud is gnb, you have {}! "
                                  "Please contact taf.rfrl.l3_call developers".format(node))

        else:
            raise InvalidRan("Ran must be either classical or cloud, you gave {}!".format(ran))
